[System]
Ты senior React разработчик внутри Code Studio.
Твоя задача — создавать и итерировать React прототипы.
Отвечай на языке пользователя (русский если пишут по-русски).
При генерации кода — полный рабочий компонент.
Будь конкретным, без лишних слов.

[Current Message]
[User]
[User]
You are a Senior Tech Lead at a top Silicon Valley startup.

You receive a PRODUCT PLAN from a product leader.
Your task is to convert it into a precise implementation blueprint for a developer.

IMPORTANT:
- PRODUCT PLAN remains the source of truth
- TECHNICAL BLUEPRINT is an implementation guide, not a replacement for the plan
- Do NOT invent onboarding, paywall, settings, auth, or premium logic unless the plan requires them
- Do NOT add features that are not supported by the plan
- Make implicit implementation requirements explicit: routing, state ownership, persistence, loading/error handling, and file responsibilities

Output ONLY valid JSON. No markdown.

Use this schema:

{
  "technicalBlueprint": {
    "appShell": {
      "routingStrategy": "How routing should be structured",
      "stateStrategy": "What belongs in app-level shared state vs page-local state",
      "persistenceStrategy": "Which localStorage or persistence keys are needed and why",
      "guardStrategy": "How semantic guards from the plan should be implemented"
    },
    "fileStructure": [
      {
        "file": "App.tsx",
        "purpose": "Top-level shell responsibility"
      }
    ],
    "componentContracts": [
      {
        "file": "pages/Home.tsx",
        "responsibility": "What this file owns",
        "mustRender": [
          "Required sections from the plan"
        ],
        "uses": [
          "Important components, hooks, or utilities"
        ],
        "localState": [
          "Minimal local UI state"
        ],
        "sideEffects": [
          "Required effects such as loading persisted data"
        ]
      }
    ],
    "dataFlow": {
      "entities": [
        {
          "name": "EntityName",
          "source": "seed|localStorage|derived",
          "consumedBy": ["pages/Home.tsx"]
        }
      ],
      "seedData": {
        "needed": false,
        "variable": "Optional constant or initializer name",
        "notes": "How seed data should be structured if required"
      }
    },
    "criticalPaths": [
      {
        "name": "Primary user flow",
        "steps": [
          "Route enters here",
          "User performs core action",
          "State updates here",
          "Guard or premium check happens here if required by plan"
        ]
      }
    ],
    "implementationRisks": [
      "Potential weak points the coder must avoid"
    ]
  }
}

[User]
PRODUCT PLAN:
{
  "id": "verified-android-identity-console",
  "appName": "Verified Android Identity Console",
  "description": "Guides indie Android teams through Google’s new developer verification, package registration, and advanced sideloading flow so releases keep shipping.",
  "theme": "neon",
  "targetUser": "Lead Android engineer at a fintech startup distributing outside Play Store in Brazil and Indonesia.",
  "marketContext": "Google has opened Android developer verification to all developers this March and starts surfacing Android Developer Verifier in April while mandating registration before the September 30 rollout in Brazil, Indonesia, Singapore, and Thailand plus adding a 24-hour advanced sideloading wait, so teams need compliance tooling immediately. ([developer.android.com](https://developer.android.com/developer-verification?utm_source=openai))",
  "targetAudience": "Independent or boutique Android teams monetizing through third-party stores who face imminent verification deadlines.",
  "painPoint": "They must gather legal identity proofs and package attestations because Google cites 90x more malware from sideloaded sources, and failure means blocked installs in their launch markets. ([androidsage.com](https://www.androidsage.com/2026/03/31/how-to-sideload-apps-on-android-after-april-2026/?utm_source=openai))",
  "competitorGap": "Project trackers ignore identity-proof uploads, verifier status, and per-market enforcement timers, leaving developers juggling spreadsheets and risking missed deadlines.",
  "generatedAt": "2026-04-11T00:04:39.122Z",
  "productStrategy": {
    "coreAction": "Auto-check every app package against Google’s verification steps, deadlines, and document requirements, surfacing gaps instantly.",
    "retentionLoop": "Daily reminders for expiring IDs plus a “launch readiness” badge that updates as markets roll out enforcement.",
    "businessModel": "freemium",
    "paywall": {
      "needed": true,
      "trigger": "After 3 registered package workspaces",
      "lockedFeature": "Automated evidence exports for legal teams plus multi-market rollout simulations",
      "upgradeMessage": "Upgrade to auto-generate regulator-ready packets and forecast rollout risks across additional markets."
    }
  },
  "userJourney": {
    "onboarding": {
      "needed": true,
      "reason": "We need distribution channels, target countries, and app counts to load the right checklists.",
      "steps": [
        {
          "question": "Where do you distribute today?",
          "type": "multi-choice",
          "options": [
            "Google Play",
            "Samsung Galaxy Store",
            "Direct APK download",
            "Third-party app store"
          ],
          "storesIn": "devProfile.channels"
        },
        {
          "question": "Which priority markets enforce verification first?",
          "type": "multi-choice",
          "options": [
            "Brazil",
            "Indonesia",
            "Singapore",
            "Thailand"
          ],
          "storesIn": "devProfile.priorityMarkets"
        },
        {
          "question": "How many apps must be registered?",
          "type": "single-choice",
          "options": [
            "1",
            "2-5",
            "6-10",
            "11+"
          ],
          "storesIn": "devProfile.appVolume"
        }
      ],
      "completionAction": "After onboarding → navigate to / showing per-market timelines and checklist progress."
    },
    "firstSession": "The engineer lands on Home and sees a neon dashboard with a verification progress donut, a timeline of Google’s milestones, and cards for each app with status chips (ID proof pending, package signature uploaded, advanced flow readiness). They click into one app, upload a D-U-N-S letter, and mark legal contact verified.",
    "returningSession": "Next day they are greeted with updated countdowns per market, alerts about remaining documents, and suggested tasks such as rehearsing the advanced flow or inviting legal review before Brazil’s enforcement date."
  },
  "layout": {
    "type": "tabs",
    "navigation": "top-nav",
    "primaryColor": "electric cyan"
  },
  "uxPatterns": {
    "emptyStates": true,
    "loadingSkeletons": true,
    "searchAndFilter": true,
    "animations": "subtle"
  },
  "responsiveness": {
    "primaryDevice": "desktop",
    "mobileFirst": true,
    "maxWidth": "max-w-4xl"
  },
  "pages": [
    {
      "path": "/onboarding",
      "name": "Onboarding",
      "file": "pages/Onboarding.tsx",
      "purpose": "Collect minimum user data to personalize the experience",
      "isMainScreen": false,
      "showInNav": false,
      "guard": "show only if !localStorage.getItem('onboarding_complete')",
      "uiSpec": "A neon-accented wizard slides in as a centered card with a progress rail up top and contextual help links to Google’s policy page. Each step uses pill buttons with iconography (e.g., store logos, country flags) so developers can tap quickly, and helper copy references why Google is asking for verification. A live summary chip list floats on the right and collapses below on mobile. Error handling highlights unmet requirements in magenta and shakes the card gently. The final step previews which checklists will be activated; pressing “Launch Console” writes onboarding_complete and routes to Home."
    },
    {
      "path": "/",
      "name": "Home",
      "file": "pages/Home.tsx",
      "purpose": "Main workspace",
      "isMainScreen": true,
      "showInNav": true,
      "guard": "redirect to /onboarding if !onboarding_complete",
      "uiSpec": "Home uses a top hero showing total verification completion, the soonest enforcement deadline, and a CTA to rehearse the advanced flow. Below, tabbed sections split into “Apps,” “Documents,” and “Markets.” The Apps tab lists cards per package with progress bars for ID verification, package claim, limited-distribution prep, and advanced flow rehearsal, plus buttons to upload new artifacts. Documents tab offers a kanban for legal IDs, D-U-N-S proof, government IDs, and invoices, supporting drag-and-drop uploads with immediate status chips. Markets tab renders a timeline with Google milestones, countdown badges, and risk alerts (e.g., “Brazil - 172 days remaining”). Empty states provide quick actions to import Play Console data. A floating “Add App” button opens a modal to capture package names and signing key fingerprints. Mobile collapses tabs into a segmented control and stacks cards vertically."
    },
    {
      "path": "/settings",
      "name": "Settings",
      "file": "pages/Settings.tsx",
      "purpose": "User preferences, account, subscription status",
      "isMainScreen": false,
      "showInNav": true,
      "uiSpec": "Settings starts with Developer Profile, showing organization name, legal contact, D-U-N-S number, and verified status badges plus edit buttons. Notification preferences let teams toggle Slack or email digests for upcoming verification steps and 24-hour advanced flow rehearsals. Subscription section outlines current tier, usage vs limit of tracked apps, upgrade CTA, and invoices. Integrations allow connecting GitHub, Google Workspace, or ticketing webhooks to sync verification tasks. Data section offers export of compliance evidence, deletion of sandbox data, and regeneration of API keys. A final Help panel links to Android policy docs and offers a “Request review” button that triggers a checklist QA. Layout stays single column on mobile with sticky Save controls."
    }
  ],
  "authFlow": {
    "type": "local-only",
    "localFirst": true,
    "reason": "Prototype stores verification metadata locally to keep the flow fast before wiring into real consoles."
  },
  "dataModel": {
    "entities": [
      {
        "name": "DeveloperProfile",
        "fields": "id: string, channels: string[], priorityMarkets: string[], appVolumeBracket: string",
        "storage": "localStorage key: 'developer_profile'"
      },
      {
        "name": "AppEntry",
        "fields": "id: string, packageName: string, verificationStatus: string, marketTargets: string[], documents: string[]",
        "storage": "localStorage key: 'app_entries'"
      },
      {
        "name": "VerificationTask",
        "fields": "id: string, appId: string, title: string, dueDate: string, status: 'todo'|'in_progress'|'done', blocker: string",
        "storage": "localStorage key: 'verification_tasks'"
      }
    ],
    "seedData": {
      "needed": true,
      "reason": "Engineers need sample apps and deadlines to see risk immediately.",
      "examples": [
        "AppEntry com.paywave.lite targeting Brazil/Indonesia with verificationStatus 'ID proof pending'.",
        "VerificationTask TASK-009 upload D-U-N-S letter for Singapore enforcement due Apr 18 2026.",
        "AppEntry com.edgewallet.pro marked 'advanced flow rehearsal required' for Thailand rollout."
      ]
    },
    "sharedState": "App.tsx holds developerProfile, selectedTab, alertFeed, activeAppId, and paywall modal state."
  },
  "criticalUiRules": [
    "Always pin the earliest enforcement deadline chip to the top hero regardless of scroll.",
    "Do not allow export buttons until every required document slot for that market is populated to prevent empty packets."
  ],
  "shadcnComponents": [
    "Button",
    "Card",
    "Input",
    "Accordion",
    "Table"
  ],
  "icons": [
    "Home",
    "Settings",
    "BadgeCheck"
  ]
}

